-- Visitors' copies of the demo organization (ADR 0011). Generated by drizzle-kit from
-- src/db/schema.ts, then the privileges and the two functions added by hand. RLS is enabled and not
-- forced, with no policy: the owner, which owns the table, reads it for the clean-up, and the app
-- role gets no privilege on it and reaches it only through the functions below.
CREATE TABLE "visitor_copies" (
	"token_hash" "bytea" PRIMARY KEY NOT NULL,
	"organization_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"last_saved_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "visitor_copies_organization_id_unique" UNIQUE("organization_id"),
	CONSTRAINT "visitor_copies_token_hash_check" CHECK (octet_length(token_hash) = 32),
	CONSTRAINT "visitor_copies_not_the_demo_check" CHECK (organization_id <> '6d656d6f-0000-4000-8000-000000000001')
);
--> statement-breakpoint
ALTER TABLE "visitor_copies" ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint

-- Default privileges (migration 0000) gave the app role every table in public: not this one.
REVOKE ALL ON TABLE "visitor_copies" FROM squadio_app;
--> statement-breakpoint

-- The organization of the copy a token hash maps to, or null. SECURITY DEFINER, so it reads the
-- table as its owner; it only ever returns the row of the hash it is given.
CREATE FUNCTION app.visitor_organization(hash bytea) RETURNS uuid
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path = pg_catalog, pg_temp
  AS $$ SELECT v.organization_id FROM public.visitor_copies v WHERE v.token_hash = hash $$;
--> statement-breakpoint
REVOKE EXECUTE ON FUNCTION app.visitor_organization(bytea) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.visitor_organization(bytea) TO squadio_app;
--> statement-breakpoint

-- Maps a token hash to a new copy's organization, or touches an existing mapping on a later save.
-- Returns why, so the caller can say so: 'claimed' (a new mapping), 'touched' (the hash already
-- maps to that organization), 'taken' (the hash maps to another organization, or the organization
-- has another visitor) or 'limit' (200 copies were made in the last day, ADR 0011 "Abuse"). The
-- demo template can never be claimed: the table's check refuses it.
--
-- New claims take a transaction lock, so concurrent first saves cannot pass the limit together.
-- That relies on READ COMMITTED, the default, where the count after the lock sees every claim
-- committed before it; the lock lasts until the copy's transaction ends, which is short.
CREATE FUNCTION app.claim_visitor_copy(hash bytea, organization uuid) RETURNS text
  LANGUAGE plpgsql
  VOLATILE
  SECURITY DEFINER
  SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  mapped uuid;
BEGIN
  SELECT v.organization_id INTO mapped FROM public.visitor_copies v WHERE v.token_hash = hash;
  IF FOUND THEN
    IF mapped <> organization THEN
      RETURN 'taken';
    END IF;
    UPDATE public.visitor_copies v SET last_saved_at = now() WHERE v.token_hash = hash;
    RETURN 'touched';
  END IF;

  -- Keyed on the table itself, so the lock cannot collide with another advisory lock.
  PERFORM pg_advisory_xact_lock('public.visitor_copies'::regclass::oid::int, 0);
  IF (SELECT count(*) FROM public.visitor_copies v WHERE v.created_at > now() - interval '1 day')
     >= 200 THEN
    RETURN 'limit';
  END IF;
  INSERT INTO public.visitor_copies (token_hash, organization_id)
    VALUES (hash, organization)
    ON CONFLICT DO NOTHING;
  RETURN CASE WHEN FOUND THEN 'claimed' ELSE 'taken' END;
END
$$;
--> statement-breakpoint
REVOKE EXECUTE ON FUNCTION app.claim_visitor_copy(bytea, uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.claim_visitor_copy(bytea, uuid) TO squadio_app;
